```turtle
@prefix ea:   <http://example.org/onto/assessment#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

<http://example.org/onto/assessment> a owl:Ontology ;
  rdfs:label "Educational Assessment Ontology" .

#################################################################
# TOP CLASS
#################################################################

ea:EducationalAssessment a owl:Class ;
  rdfs:label "Educational Assessment" ;
  skos:altLabel "assessment", "educational evaluation" ;
  rdfs:comment "Systematic process of documenting and using empirical data on knowledge, skill, attitudes, aptitude and beliefs to refine programs and improve student learning. Often used interchangeably with 'test' but not limited to tests." .

#################################################################
# GRANULARITY AXIS
#################################################################

ea:hasGranularity a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:GranularityLevel .

ea:GranularityLevel a owl:Class .
ea:LearnerGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:LearningCommunityGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:CourseGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:ProgramGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:InstitutionGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:EducationalSystemGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:GranularityLevel owl:disjointUnionOf
  ( ea:LearnerGranularity ea:LearningCommunityGranularity ea:CourseGranularity
    ea:ProgramGranularity ea:InstitutionGranularity ea:EducationalSystemGranularity ) .

#################################################################
# AXIS 1: PURPOSE / TIMING  (placement, formative, summative, diagnostic)
#################################################################

ea:hasPurpose a owl:ObjectProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:AssessmentPurpose .

ea:AssessmentPurpose a owl:Class .
ea:PlacementPurpose a owl:Class ; rdfs:subClassOf ea:AssessmentPurpose .
ea:FormativePurpose a owl:Class ; rdfs:subClassOf ea:AssessmentPurpose .
ea:SummativePurpose a owl:Class ; rdfs:subClassOf ea:AssessmentPurpose .
ea:DiagnosticPurpose a owl:Class ; rdfs:subClassOf ea:AssessmentPurpose .
ea:AssessmentPurpose owl:disjointUnionOf
  ( ea:PlacementPurpose ea:FormativePurpose ea:SummativePurpose ea:DiagnosticPurpose ) .

ea:PlacementAssessment a owl:Class ;
  skos:altLabel "pre-assessment", "initial assessment", "threshold knowledge test" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:PlacementPurpose ] ) ] ;
  rdfs:subClassOf ea:EducationalAssessment .

ea:FormativeAssessment a owl:Class ;
  skos:altLabel "formative evaluation", "assessment for learning", "educative assessment", "classroom assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:FormativePurpose ] ) ] ;
  rdfs:subClassOf ea:EducationalAssessment .

ea:SummativeAssessment a owl:Class ;
  skos:altLabel "summative evaluation", "assessment of learning" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:SummativePurpose ] ) ] ;
  rdfs:subClassOf ea:EducationalAssessment .

ea:DiagnosticAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:DiagnosticPurpose ] ) ] ;
  rdfs:subClassOf ea:EducationalAssessment ;
  rdfs:subClassOf ea:FormativeAssessment ;
  rdfs:comment "TENSION: one passage lists diagnostic assessment as the fourth coordinate category alongside placement, formative and summative (hence modelled via the purpose value-partition as a sibling). Other passages state 'A common form of formative assessment is diagnostic assessment' and define formative assessment as 'including diagnostic testing', i.e. diagnostic assessment is subordinate to formative assessment. Both the coordinate (disjoint-union sibling) and the subordinate (subClassOf FormativeAssessment) claims are encoded here." .

#################################################################
# AXIS 2: OBJECTIVE / SUBJECTIVE
#################################################################

ea:hasResponseType a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:ResponseType .

ea:ResponseType a owl:Class .
ea:ObjectiveResponseType a owl:Class ; rdfs:subClassOf ea:ResponseType .
ea:SubjectiveResponseType a owl:Class ; rdfs:subClassOf ea:ResponseType .
ea:ResponseType owl:disjointUnionOf ( ea:ObjectiveResponseType ea:SubjectiveResponseType ) .

ea:ObjectiveAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasResponseType ; owl:someValuesFrom ea:ObjectiveResponseType ] ) ] ;
  rdfs:subClassOf ea:EducationalAssessment ;
  rdfs:comment "A form of questioning that has a single correct answer." .

ea:SubjectiveAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasResponseType ; owl:someValuesFrom ea:SubjectiveResponseType ] ) ] ;
  rdfs:subClassOf ea:EducationalAssessment ;
  rdfs:comment "A form of questioning that may have more than one correct answer." .

#################################################################
# AXIS 3: REFERENCING (criterion / norm / ipsative)
#################################################################

ea:hasReferencingType a owl:ObjectProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:ReferencingType ;
  rdfs:comment "Reifies the referencing axis. The corpus notes the same test paper can be graded by either method, so this is not declared functional." .

ea:ReferencingType a owl:Class .
ea:CriterionReferencing a owl:Class ; rdfs:subClassOf ea:ReferencingType .
ea:NormReferencing a owl:Class ; rdfs:subClassOf ea:ReferencingType .
ea:IpsativeReferencing a owl:Class ; rdfs:subClassOf ea:ReferencingType .
ea:ReferencingType owl:disjointUnionOf ( ea:CriterionReferencing ea:NormReferencing ea:IpsativeReferencing ) .

ea:CriterionReferencedAssessment a owl:Class ;
  skos:altLabel "criterion-referenced test", "CRT", "standards-based assessment", "mastery test" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasReferencingType ; owl:someValuesFrom ea:CriterionReferencing ] ) ] ;
  rdfs:subClassOf ea:EducationalAssessment ;
  owl:disjointWith ea:NormReferencedAssessment ;
  owl:disjointWith ea:IpsativeAssessment .

ea:NormReferencedAssessment a owl:Class ;
  skos:altLabel "norm-referenced test", "NRT", "normative assessment", "grading on the curve" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasReferencingType ; owl:someValuesFrom ea:NormReferencing ] ) ] ;
  rdfs:subClassOf ea:EducationalAssessment .

ea:IpsativeAssessment a owl:Class ;
  skos:altLabel "ipsative test" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasReferencingType ; owl:someValuesFrom ea:IpsativeReferencing ] ) ] ;
  rdfs:subClassOf ea:EducationalAssessment .

ea:hasNormGroup a owl:ObjectProperty ;
  rdfs:domain ea:NormReferencedAssessment ;
  rdfs:range ea:NormGroup .

ea:NormGroup a owl:Class ;
  skos:altLabel "norming group" ;
  rdfs:comment "Sample drawn from a population used to derive the position estimate of a tested individual." .

ea:hasCutScore a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain ea:CriterionReferencedAssessment ;
  rdfs:range xsd:decimal .

#################################################################
# AXIS 4: FORMALITY (formal / informal)
#################################################################

ea:hasFormalityStatus a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:FormalityStatus .

ea:FormalityStatus a owl:Class .
ea:FormalStatus a owl:Class ; rdfs:subClassOf ea:FormalityStatus .
ea:InformalStatus a owl:Class ; rdfs:subClassOf ea:FormalityStatus .
ea:FormalityStatus owl:disjointUnionOf ( ea:FormalStatus ea:InformalStatus ) .

ea:FormalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasFormalityStatus ; owl:someValuesFrom ea:FormalStatus ] ) ] ;
  rdfs:subClassOf ea:EducationalAssessment .

ea:InformalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasFormalityStatus ; owl:someValuesFrom ea:InformalStatus ] ) ] ;
  rdfs:subClassOf ea:EducationalAssessment .

#################################################################
# AXIS 5: LOCUS (internal / external)
#################################################################

ea:hasLocus a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:AssessmentLocus .

ea:AssessmentLocus a owl:Class .
ea:InternalLocus a owl:Class ; rdfs:subClassOf ea:AssessmentLocus .
ea:ExternalLocus a owl:Class ; rdfs:subClassOf ea:AssessmentLocus .
ea:AssessmentLocus owl:disjointUnionOf ( ea:InternalLocus ea:ExternalLocus ) .

ea:InternalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasLocus ; owl:someValuesFrom ea:InternalLocus ] ) ] ;
  rdfs:subClassOf ea:EducationalAssessment .

ea:ExternalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasLocus ; owl:someValuesFrom ea:ExternalLocus ] ) ] ;
  rdfs:subClassOf ea:EducationalAssessment .

#################################################################
# TEST / EXAMINATION
#################################################################

ea:Test a owl:Class ;
  skos:altLabel "examination", "exam", "evaluation" ;
  rdfs:subClassOf ea:EducationalAssessment ;
  rdfs:comment "An educational assessment intended to measure a test-taker's knowledge, skill, aptitude, physical fitness, or classification." .

ea:hasItemCount a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ;
  rdfs:range xsd:integer .

ea:hasItem a owl:ObjectProperty ;
  rdfs:domain ea:Test ;
  rdfs:range ea:TestItem .

ea:isItemOf a owl:ObjectProperty ;
  owl:inverseOf ea:hasItem ;
  rdfs:domain ea:TestItem ;
  rdfs:range ea:Test .

#################################################################
# AXIS 6: STANDARDIZATION
#################################################################

ea:hasStandardizationStatus a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ;
  rdfs:range ea:StandardizationStatus .

ea:StandardizationStatus a owl:Class .
ea:StandardizedStatus a owl:Class ; rdfs:subClassOf ea:StandardizationStatus .
ea:NonStandardizedStatus a owl:Class ; rdfs:subClassOf ea:StandardizationStatus .
ea:StandardizationStatus owl:disjointUnionOf ( ea:StandardizedStatus ea:NonStandardizedStatus ) .

ea:StandardizedTest a owl:Class ;
  skos:altLabel "standardized assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasStandardizationStatus ; owl:someValuesFrom ea:StandardizedStatus ] ) ] ;
  rdfs:subClassOf ea:Test ;
  rdfs:comment "Administered and scored in a consistent or standard manner for all test takers." .

ea:NonStandardizedTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasStandardizationStatus ; owl:someValuesFrom ea:NonStandardizedStatus ] ) ] ;
  rdfs:subClassOf ea:Test .

#################################################################
# AXIS 7: STAKES
#################################################################

ea:hasStakesLevel a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ;
  rdfs:range ea:StakesLevel .

ea:StakesLevel a owl:Class .
ea:HighStakes a owl:Class ; rdfs:subClassOf ea:StakesLevel .
ea:LowStakes a owl:Class ; rdfs:subClassOf ea:StakesLevel .
ea:StakesLevel owl:disjointUnionOf ( ea:HighStakes ea:LowStakes ) .

ea:HighStakesTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasStakesLevel ; owl:someValuesFrom ea:HighStakes ] ) ] ;
  rdfs:subClassOf ea:Test ;
  rdfs:comment "A test with a desired reward or important consequence for good or bad performance." .

ea:LowStakesTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasStakesLevel ; owl:someValuesFrom ea:LowStakes ] ) ] ;
  rdfs:subClassOf ea:Test .

#################################################################
# STANDARDIZED TEST NAMED SUBTYPES (coordinate, non-exhaustive list)
#################################################################

ea:AchievementTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest ;
  rdfs:comment "Backward-looking: measures knowledge and skills already learned." .
ea:AptitudeTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest ;
  rdfs:comment "Forward-looking: attempts to predict ability to succeed in a future endeavor." .
ea:CollegeAdmissionsTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:InternationalComparisonTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:PsychologicalTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:AchievementTest ea:AptitudeTest ea:CollegeAdmissionsTest
                ea:InternationalComparisonTest ea:PsychologicalTest ) .

ea:CompetitiveExamination a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf
    ( ea:NormReferencedAssessment ea:HighStakesTest ea:StandardizedTest ) ] ;
  rdfs:subClassOf ea:Test ;
  rdfs:comment "Candidates are ranked by grade/percentile and the top n candidates are selected." .

ea:MidtermExam a owl:Class ;
  rdfs:subClassOf ea:Test ;
  rdfs:subClassOf [ a owl:Class ; owl:unionOf ( ea:FormativeAssessment ea:SummativeAssessment ) ] ;
  rdfs:comment "Given near the middle of a grading term; corpus states it is 'a type of formative or summative assessment'." .

ea:FinalExam a owl:Class ;
  rdfs:subClassOf ea:Test ;
  rdfs:subClassOf ea:SummativeAssessment .

ea:Quiz a owl:Class ;
  rdfs:subClassOf ea:Test ;
  rdfs:subClassOf ea:FormativeAssessment ;
  rdfs:comment "A brief assessment covering a small amount of material; instructors usually provide it as a formative assessment." .

#################################################################
# TEST ITEM FORMATS  (objective / subjective)
#################################################################

ea:TestItem a owl:Class .
ea:ObjectiveTestItem a owl:Class ; rdfs:subClassOf ea:TestItem .
ea:SubjectiveTestItem a owl:Class ; rdfs:subClassOf ea:TestItem .
ea:TestItem owl:disjointUnionOf ( ea:ObjectiveTestItem ea:SubjectiveTestItem ) .

ea:MultipleChoiceItem a owl:Class ; rdfs:subClassOf ea:ObjectiveTestItem ;
  skos:altLabel "MCQ", "multiple choice question" .
ea:TrueFalseItem a owl:Class ; rdfs:subClassOf ea:ObjectiveTestItem .
ea:MultipleResponseItem a owl:Class ; rdfs:subClassOf ea:ObjectiveTestItem ;
  rdfs:comment "More than one answer may be keyed as correct, contrasted with MultipleChoiceItem." .
ea:MatchingItem a owl:Class ; rdfs:subClassOf ea:ObjectiveTestItem .
ea:FillInTheBlankItem a owl:Class ; rdfs:subClassOf ea:ObjectiveTestItem .

ea:ShortAnswerItem a owl:Class ; rdfs:subClassOf ea:SubjectiveTestItem .
ea:EssayItem a owl:Class ; rdfs:subClassOf ea:SubjectiveTestItem ;
  skos:altLabel "free response question", "FRQ", "extended-response item" .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:MultipleChoiceItem ea:TrueFalseItem ea:MultipleResponseItem
                ea:MatchingItem ea:FillInTheBlankItem ) .

ea:hasStem a owl:DatatypeProperty ; rdfs:domain ea:MultipleChoiceItem ; rdfs:range xsd:string .
ea:hasKey a owl:DatatypeProperty, owl:FunctionalProperty ; rdfs:domain ea:MultipleChoiceItem ; rdfs:range xsd:string .
ea:hasDistractor a owl:DatatypeProperty ; rdfs:domain ea:MultipleChoiceItem ; rdfs:range xsd:string .

#################################################################
# PERFORMANCE / AUTHENTIC ASSESSMENT
#################################################################

ea:hasContext a owl:ObjectProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:AssessmentContext .

ea:AssessmentContext a owl:Class .
ea:RealWorldContext a owl:Class ; rdfs:subClassOf ea:AssessmentContext .

ea:PerformanceBasedAssessment a owl:Class ;
  rdfs:subClassOf ea:EducationalAssessment ;
  rdfs:comment "Requires students to solve real-world problems or produce something with real-world application; similar to summative assessment in focusing on achievement." .

ea:AuthenticAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasContext ; owl:someValuesFrom ea:RealWorldContext ] ) ] ;
  rdfs:subClassOf ea:EducationalAssessment ;
  owl:equivalentClass ea:PerformanceBasedAssessment ;
  rdfs:comment "TENSION: one enumerated list ('Assessment types include...') presents Performance-based assessment and Authentic assessment as two coordinate, separately-named types. Another passage states 'Performance assessments may also be called authentic assessments', i.e. the same concept. Both the coordinate listing (two labelled classes) and the stated equivalence (owl:equivalentClass) are encoded." .

ea:PerformanceFormat a owl:Class .
ea:PerformanceProduct a owl:Class ; rdfs:subClassOf ea:PerformanceFormat ;
  rdfs:comment "e.g. a painting, portfolio, paper, or exhibition." .
ea:PerformanceAct a owl:Class ; rdfs:subClassOf ea:PerformanceFormat ;
  rdfs:comment "e.g. a speech, athletic skill, musical recital, or reading." .
ea:PerformanceFormat owl:disjointUnionOf ( ea:PerformanceProduct ea:PerformanceAct ) .

ea:hasPerformanceFormat a owl:ObjectProperty ;
  rdfs:domain ea:PerformanceBasedAssessment ;
  rdfs:range ea:PerformanceFormat .

ea:Portfolio a owl:Class ;
  skos:altLabel "student portfolio", "e-portfolio", "digital portfolio" ;
  rdfs:subClassOf ea:PerformanceProduct .

#################################################################
# OTHER NAMED ASSESSMENT KINDS
#################################################################

ea:ContinuousAssessment a owl:Class ;
  rdfs:subClassOf ea:EducationalAssessment ;
  rdfs:comment "Evaluates a student's progress throughout a prescribed course; often includes formative assessment; alternative to the final-examination system." .

ea:ComplexAssessment a owl:Class ;
  rdfs:subClassOf ea:EducationalAssessment ;
  rdfs:comment "Requires a rubric and an expert examiner, e.g. a thesis or funding proposal." .

ea:CommonAssessment a owl:Class ;
  rdfs:subClassOf ea:EducationalAssessment ;
  rdfs:comment "Used across teachers/classrooms to promote consistent evaluation; may be formative or summative." .

ea:InterimAssessment a owl:Class ;
  rdfs:subClassOf ea:EducationalAssessment ;
  skos:altLabel "benchmark assessment" ;
  rdfs:comment "Periodically administered, separate from instruction, to check progress toward later summative assessments. Corpus notes debate over whether this is formative or summative." .

ea:ScreeningAssessment a owl:Class ;
  rdfs:subClassOf ea:EducationalAssessment .

ea:ForwardLookingAssessment a owl:Class ;
  rdfs:subClassOf ea:EducationalAssessment ;
  rdfs:comment "Asks those being assessed to consider themselves in hypothetical future situations." .

#################################################################
# RUBRIC HIERARCHY
#################################################################

ea:Rubric a owl:Class ;
  skos:altLabel "scoring guide" ;
  rdfs:comment "A scoring guide used to evaluate the quality of students' constructed responses." .

ea:hasRubric a owl:ObjectProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:Rubric .

ea:HolisticRubric a owl:Class ; rdfs:subClassOf ea:Rubric ;
  rdfs:comment "Provides an overall rating for a piece of work, considering all aspects." .
ea:AnalyticRubric a owl:Class ; rdfs:subClassOf ea:Rubric ;
  rdfs:comment "Evaluates various dimensions or components separately." .
ea:DevelopmentalRubric a owl:Class ;
  rdfs:subClassOf ea:AnalyticRubric ;
  rdfs:comment "A subset of analytic rubrics that facilitates assessment, instructional design, and transformative learning through multiple dimensions of developmental succession." .

ea:Rubric owl:disjointUnionOf ( ea:HolisticRubric ea:AnalyticRubric ) .

#################################################################
# GRADING / SCORING METHODS
#################################################################

ea:GradingMethod a owl:Class .

ea:HolisticGrading a owl:Class ;
  skos:altLabel "holistic scoring", "nonreductionist grading" ;
  rdfs:subClassOf ea:GradingMethod ;
  rdfs:comment "Bases a grade on a paper's overall quality, treating the composition as a whole." .

ea:AnalyticGrading a owl:Class ;
  rdfs:subClassOf ea:GradingMethod ;
  rdfs:comment "Involves criterion-by-criterion judgments, taking more factors into account." .

ea:GradingMethod owl:disjointUnionOf ( ea:HolisticGrading ea:AnalyticGrading ) .

ea:TraitInformedScoring a owl:Class ;
  rdfs:subClassOf ea:GradingMethod ;
  rdfs:comment "Trains raters to score against a rubric with scaled criteria; close to analytic scoring but remains holistic at its core (uses a single final score)." .

#################################################################
# VALIDITY
#################################################################

ea:Validity a owl:Class ;
  rdfs:comment "The degree to which a measurement tool measures what it claims to measure." .

ea:hasValidityEvidence a owl:ObjectProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:Validity .

ea:ContentValidity a owl:Class ; rdfs:subClassOf ea:Validity ;
  skos:altLabel "logical validity" .
ea:CriterionValidity a owl:Class ; rdfs:subClassOf ea:Validity ;
  skos:altLabel "criterion-related validity" .
ea:ConstructValidity a owl:Class ; rdfs:subClassOf ea:Validity .
ea:FaceValidity a owl:Class ; rdfs:subClassOf ea:Validity .
ea:ConsequentialValidity a owl:Class ; rdfs:subClassOf ea:Validity .

ea:ContentValidity rdfs:subClassOf ea:ConstructValidity .
ea:CriterionValidity rdfs:subClassOf ea:ConstructValidity .
ea:FaceValidity rdfs:subClassOf ea:ConstructValidity .

ea:ConstructValidity rdfs:comment "TENSION: one passage enumerates Content, Criterion, and Construct validity as coordinate evidence categories (plus Consequential and Face validity as 'others'), modelled as sibling subclasses of Validity. Another passage states construct validity 'subsumes all other types of validity', modelled by asserting ContentValidity, CriterionValidity and FaceValidity as subClassOf ConstructValidity. Both claims are retained." .

ea:ConcurrentValidity a owl:Class ; rdfs:subClassOf ea:CriterionValidity .
ea:PredictiveValidity a owl:Class ; rdfs:subClassOf ea:CriterionValidity .
ea:CriterionValidity owl:disjointUnionOf ( ea:ConcurrentValidity ea:PredictiveValidity ) .

ea:ConvergentValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity .
ea:DiscriminantValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity .
ea:ConvergentValidity owl:disjointWith ea:DiscriminantValidity .

#################################################################
# RELIABILITY
#################################################################

ea:Reliability a owl:Class ;
  rdfs:comment "Consistency of an assessment; the proportion of observed score variation due to true score variation." .

ea:hasReliability a owl:ObjectProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:Reliability .

ea:hasReliabilityCoefficient a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Reliability ;
  rdfs:range xsd:decimal .

ea:ReliabilityEstimationMethod a owl:Class ;
  rdfs:comment "Classes of reliability estimates / practical strategies for estimating test reliability." .

ea:InterRaterReliability a owl:Class ; rdfs:subClassOf ea:ReliabilityEstimationMethod .
ea:TestRetestReliability a owl:Class ; rdfs:subClassOf ea:ReliabilityEstimationMethod ;
  skos:altLabel "repeatability" .
ea:ParallelFormsReliability a owl:Class ; rdfs:subClassOf ea:ReliabilityEstimationMethod ;
  skos:altLabel "inter-method reliability", "equivalent-forms reliability" .
ea:SplitHalfReliability a owl:Class ; rdfs:subClassOf ea:ParallelFormsReliability ;
  rdfs:comment "Treats the two halves of a measure as alternate forms." .
ea:InternalConsistencyReliability a owl:Class ; rdfs:subClassOf ea:ReliabilityEstimationMethod .

ea:ReliabilityEstimationMethod owl:disjointUnionOf
  ( ea:InterRaterReliability ea:TestRetestReliability ea:ParallelFormsReliability
    ea:InternalConsistencyReliability ) .

ea:usesEstimationMethod a owl:ObjectProperty ;
  rdfs:domain ea:Reliability ;
  rdfs:range ea:ReliabilityEstimationMethod .

ea:ReliabilitySource a owl:Class ;
  rdfs:comment "The corpus states there are four types of reliability based on the source of inconsistency: student-related, rater-related, test-administration-related and test-related." .
ea:StudentRelatedReliabilitySource a owl:Class ; rdfs:subClassOf ea:ReliabilitySource .
ea:RaterRelatedReliabilitySource a owl:Class ; rdfs:subClassOf ea:ReliabilitySource .
ea:TestAdministrationRelatedReliabilitySource a owl:Class ; rdfs:subClassOf ea:ReliabilitySource .
ea:TestRelatedReliabilitySource a owl:Class ; rdfs:subClassOf ea:ReliabilitySource .
ea:ReliabilitySource owl:disjointUnionOf
  ( ea:StudentRelatedReliabilitySource ea:RaterRelatedReliabilitySource
    ea:TestAdministrationRelatedReliabilitySource ea:TestRelatedReliabilitySource ) .

ea:hasReliabilitySource a owl:ObjectProperty ;
  rdfs:domain ea:Reliability ;
